import json
from orca_task_sdk import run_orca, receipt_source

def read(path):
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        return f.read()

def parse_tensor(text):
    lines = text.splitlines()
    vals = []
    iso = None
    for i, line in enumerate(lines):
        low = line.lower()
        if 'raw cartesian tensor' in low:
            for line2 in lines[i+1:i+12]:
                parts = line2.split()
                if len(parts) >= 3:
                    try:
                        row = [float(parts[0]), float(parts[1]), float(parts[2])]
                    except ValueError:
                        continue
                    vals.append(row)
                    if len(vals) == 3:
                        break
        if 'isotropic polarizability' in low and ':' in line:
            try:
                iso = float(line.split(':')[-1].strip())
            except ValueError:
                pass
    if len(vals) != 3 or iso is None:
        raise RuntimeError('could not parse static polarizability tensor or isotropic value')
    return vals, iso

xyz = read('coords.xyz')
with open('original.xyz', 'w', encoding='utf-8') as f:
    f.write(xyz)
inp = '''! RHF def2-SVP NoAutoStart
%maxcore 192
%scf MaxIter 200 AutoTRAH false end
%elprop Polar true end
* xyzfile 0 1 original.xyz
'''
with open('original.inp', 'w', encoding='utf-8') as f:
    f.write(inp)
receipt = run_orca('original.inp', dependencies=['original.xyz'], request_key='polar_original', purpose='new_candidate')
files = receipt.get('files', {})
texts = []
for key, path in files.items():
    if key.endswith(('.out', '.txt', '.log', '.property.txt')):
        try:
            texts.append((key, read(path)))
        except Exception:
            pass
tensor = None
iso = None
parsed_key = None
for key, text in texts:
    try:
        tensor, iso = parse_tensor(text)
        parsed_key = key
        break
    except Exception:
        continue
if tensor is None:
    raise RuntimeError('static polarizability tensor not found in run files: ' + ', '.join(files.keys()))
data = {'tensor_au': tensor, 'isotropic_au': iso, 'request_key': receipt.get('request_key'), 'operation_status': receipt.get('operation_status'), 'scientific_validation': receipt.get('scientific_validation'), 'actual_conditions': receipt.get('actual_conditions')}
with open('original_tensor.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, indent=2)
with open('random_seed_record.txt', 'w', encoding='utf-8') as f:
    f.write('seed=1701; no stochastic step used in this deterministic script\n')
obs = []
src = [receipt_source(receipt, parsed_key, location='STATIC POLARIZABILITY TENSOR')]
obs.append({'name': 'static_polarizability', 'value': {'tensor_au': tensor, 'isotropic_au': iso}, 'unit': 'atomic units', 'sources': src, 'formula': 'alpha_iso=(alpha_xx+alpha_yy+alpha_zz)/3', 'artifacts': ['original.xyz', 'original.inp', 'original_tensor.json'], 'limitations': []})
obs.append({'name': 'random_seed', 'value': 1701, 'unit': None, 'sources': [{'filename': 'random_seed_record.txt', 'location': None}], 'formula': None, 'artifacts': ['random_seed_record.txt'], 'limitations': ['No stochastic algorithm was used; seed recorded per request.']})
with open('observations.json', 'w', encoding='utf-8') as f:
    json.dump({'version': 1, 'observations': obs}, f, indent=2)
